package com.financecoach.service;
import com.financecoach.dto.*; import com.financecoach.entity.*; import com.financecoach.exception.ResourceNotFoundException; import com.financecoach.repository.*; import org.springframework.data.domain.Sort; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@Service public class GoalService { private final FinancialGoalRepository repo; private final UserRepository users; public GoalService(FinancialGoalRepository repo,UserRepository users){this.repo=repo;this.users=users;}
 @Transactional(readOnly=true) public List<GoalDto> list(Long uid){return repo.findByUserId(uid,Sort.by("targetDate")).stream().map(this::dto).toList();}
 @Transactional public GoalDto create(Long uid,GoalRequest r){User u=users.findById(uid).orElseThrow(()->new ResourceNotFoundException("User not found"));return dto(repo.save(new FinancialGoal(u,r.getName(),r.getTargetAmount(),r.getCurrentAmount(),r.getTargetDate(),r.getPriority(),r.getStatus())));}
 @Transactional public GoalDto update(Long uid,Long id,GoalRequest r){FinancialGoal g=owned(uid,id);g.setName(r.getName());g.setTargetAmount(r.getTargetAmount());g.setCurrentAmount(r.getCurrentAmount());g.setTargetDate(r.getTargetDate());g.setPriority(r.getPriority());g.setStatus(r.getStatus());return dto(repo.save(g));}
 @Transactional public void delete(Long uid,Long id){repo.delete(owned(uid,id));}
 private FinancialGoal owned(Long uid,Long id){return repo.findById(id).filter(g->g.getUser().getId().equals(uid)).orElseThrow(()->new ResourceNotFoundException("Goal not found"));}
 private GoalDto dto(FinancialGoal g){BigDecimal remaining=g.getTargetAmount().subtract(g.getCurrentAmount()).max(BigDecimal.ZERO);long months=Math.max(1,ChronoUnit.MONTHS.between(YearMonth.now(),YearMonth.from(g.getTargetDate())));BigDecimal monthly=remaining.divide(BigDecimal.valueOf(months),2,RoundingMode.CEILING);return new GoalDto(g.getId(),g.getName(),g.getTargetAmount(),g.getCurrentAmount(),monthly,g.getTargetDate(),g.getPriority(),g.getStatus());}}
